class Solution:
    def dominantIndex(self, nums: List[int]) -> int:
        maxIdx = 0
        for i in range(1, len(nums)):
            if nums[i] > nums[maxIdx]:
                maxIdx = i
        second = -1
        for i, x in enumerate(nums):
            if i != maxIdx:
                second = max(second, x)
        return maxIdx if nums[maxIdx] >= 2 * second else -1

