class Solution {
public:
    int dominantIndex(vector<int>& nums) {
        int idx = 0;
        long long mx = nums[0], second = -1;
        for (int i = 1; i < nums.size(); ++i) {
            if (nums[i] > mx) { second = mx; mx = nums[i]; idx = i; }
            else if (nums[i] > second) second = nums[i];
        }
        return mx >= 2 * second ? idx : -1;
    }
};

